const coin = pm.variables.get("mainnetHcCoin") || "BTC";
const payload = pm.response.json();
const entry = (payload.universe || []).find(x => x.name === coin);
pm.test("The selected perpetual market reports its quantity precision (szDecimals)", () => {
  pm.expect(entry, coin).to.exist;
  pm.expect(Number.isInteger(entry.szDecimals)).to.eql(true);
});
if (entry) pm.visualizer.set("<h2>{{coin}}</h2><p>Quantity precision (szDecimals) = <strong>{{decimals}}</strong></p>", {coin, decimals:entry.szDecimals});

const pair = pm.variables.get("mainnetHcSpotPair") || "@107";
const payload = pm.response.json();
const market = (payload.universe || []).find(x => x.name === pair);
const tokens = new Map((payload.tokens || []).map(t => [t.index, t]));
const base = market && tokens.get(market.tokens[0]);
const quote = market && tokens.get(market.tokens[1]);
pm.test("Quantity precision is available for both the base and quote tokens", () => {
  pm.expect(base, pair).to.exist;
  pm.expect(quote, pair).to.exist;
  pm.expect(Number.isInteger(base.szDecimals)).to.eql(true);
});
if (base && quote) pm.visualizer.set("<h2>{{pair}} ({{base}}/{{quote}})</h2><p>Trade size uses the base token's precision ({{base}}, <strong>{{size}}</strong> decimal places). The quote token ({{quote}}) uses {{quoteSize}} decimal places.</p>", {pair,base:base.name,quote:quote.name,size:base.szDecimals,quoteSize:quote.szDecimals});

